package com.sisge.ms.security;
import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import com.sisge.ms.exception.ApiException;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final UserAuthenticationService users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserAuthenticationService u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public record Login(@Email String email,@NotBlank String password){} public record Token(String accessToken,String tokenType){} @PostMapping("/login") public Token login(@RequestBody @jakarta.validation.Valid Login x){var u=users.entity(x.email());if(!"ACTIVO".equals(u.getEstado())||!encoder.matches(x.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return new Token(jwt.create(u.getEmail()),"Bearer");}}
